00205   inline Distortion getBvCostMultiplePreds(int x, int y, bool useIMV)
00206   {
00207     return Distortion(m_dCost * getBitsMultiplePreds(x, y, useIMV));
00208   }
00209 
00210   unsigned int    getBitsMultiplePreds(int x, int y, bool useIMV)
00211   {
00212     int rmvH[2];
00213     int rmvV[2];
00214     rmvH[0] = x - m_bvPredictors[0].getHor();
00215     rmvH[1] = x - m_bvPredictors[1].getHor();
00216 
00217     rmvV[0] = y - m_bvPredictors[0].getVer();
00218     rmvV[1] = y - m_bvPredictors[1].getVer();
00219     int absCand[2];
00220     absCand[0] = abs(rmvH[0]) + abs(rmvV[0]);
00221     absCand[1] = abs(rmvH[1]) + abs(rmvV[1]);
00222 
00223     int rmvHQP[2];
00224     int rmvVQP[2];
00225     if (x % 4 == 0 && y % 4 == 0 && useIMV)
00226     {
00227       int imvShift = 2;
00228       int offset = 1 << (imvShift - 1);
00229 
00230       rmvHQP[0] = (x >> 2) - ((m_bvPredictors[0].getHor() + offset) >> 2);
00231       rmvHQP[1] = (x >> 2) - ((m_bvPredictors[1].getHor() + offset) >> 2);
00232       rmvVQP[0] = (y >> 2) - ((m_bvPredictors[0].getVer() + offset) >> 2);
00233       rmvVQP[1] = (y >> 2) - ((m_bvPredictors[1].getVer() + offset) >> 2);
00234 
00235       int absCandQP[2];
00236       absCandQP[0] = abs(rmvHQP[0]) + abs(rmvVQP[0]);
00237       absCandQP[1] = abs(rmvHQP[1]) + abs(rmvVQP[1]);
00238       unsigned int candBits0QP, candBits1QP;
00239       if (absCand[0] < absCand[1])
00240       {
00241         unsigned int candBits0 = getIComponentBits(rmvH[0]) + getIComponentBits(rmvV[0]);
00242         if (absCandQP[0] < absCandQP[1])
00243         {
00244           candBits0QP = getIComponentBits(rmvHQP[0]) + getIComponentBits(rmvVQP[0]);
00245           return candBits0QP <candBits0 ? candBits0QP : candBits0;
00246         }
00247         else
00248         {
00249           candBits1QP = getIComponentBits(rmvHQP[1]) + getIComponentBits(rmvVQP[1]);
00250           return candBits1QP < candBits0 ? candBits1QP : candBits0;
00251         }
00252       }
00253       else
00254       {
00255         unsigned int candBits1 = getIComponentBits(rmvH[1]) + getIComponentBits(rmvV[1]);
00256         if (absCandQP[0] < absCandQP[1])
00257         {
00258           candBits0QP = getIComponentBits(rmvHQP[0]) + getIComponentBits(rmvVQP[0]);
00259           return candBits0QP < candBits1 ? candBits0QP : candBits1;
00260         }
00261         else
00262         {
00263           candBits1QP = getIComponentBits(rmvHQP[1]) + getIComponentBits(rmvVQP[1]);
00264           return candBits1QP < candBits1 ? candBits1QP : candBits1;
00265         }
00266       }
00267     }
00268     else
00269 
00270     {
00271       if (absCand[0] < absCand[1])
00272       {
00273         return getIComponentBits(rmvH[0]) + getIComponentBits(rmvV[0]);
00274       }
00275       else
00276       {
00277         return getIComponentBits(rmvH[1]) + getIComponentBits(rmvV[1]);
00278       }
00279     }
00280   }
00281 
00282   unsigned int getIComponentBits(int val)
00283   {
00284     if (!val) return 1;
00285 
00286     unsigned int length = 1;
00287     unsigned int temp = (val <= 0) ? (-val << 1) + 1 : (val << 1);
00288 
00289     while (1 != temp)
00290     {
00291       temp >>= 1;
00292       length += 2;
00293     }
00294 
00295     return length;
00296   }
