00302   // for motion cost
00303   static uint32_t    xGetExpGolombNumberOfBits( int iVal )
00304   {
00305     CHECKD( iVal == std::numeric_limits<int>::min(), "Wrong value" );
00306     unsigned uiLength2 = 1, uiTemp2 = ( iVal <= 0 ) ? ( unsigned( -iVal ) << 1 ) + 1 : unsigned( iVal << 1 );
00307 
00308     while( uiTemp2 > MAX_CU_SIZE )
00309     {
00310       uiLength2 += ( MAX_CU_DEPTH << 1 );
00311       uiTemp2  >>=   MAX_CU_DEPTH;
00312     }
00313 
00314     return uiLength2 + ( floorLog2(uiTemp2) << 1 );
00315   }
00316   Distortion     getCostOfVectorWithPredictor( const int x, const int y, const unsigned imvShift )  { return Distortion( m_motionLambda * getBitsOfVectorWithPredictor(x, y, imvShift )); }
00317   uint32_t           getBitsOfVectorWithPredictor( const int x, const int y, const unsigned imvShift )  { return xGetExpGolombNumberOfBits(((x << m_iCostScale) - m_mvPredictor.getHor())>>imvShift) + xGetExpGolombNumberOfBits(((y << m_iCostScale) - m_mvPredictor.getVer())>>imvShift); }
